{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Elbasvir, the closest structural analogue (Morgan similarity 0.6098) and a member of the same HCV NS5A inhibitor class with the same imidazole-pyrrolidine carbamate pharmacophores, has an absolute oral bioavailability of approximately 32% in HCV-infected subjects, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ledipasvir, another closely related HCV NS5A inhibitor (Morgan similarity 0.4433) sharing the same carbamate and imidazole-pyrrolidine framework, shows an oral bioavailability of 53% in humans, providing independent support for high oral bioavailability of the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a symmetric HCV NS5A inhibitor closely related to elbasvir and ledipasvir. The highest-transfer analogue, elbasvir, has an absolute oral bioavailability of about 32%, and ledipasvir has about 53%, both above the 20% threshold. Lower-similarity molecules with poor bioavailability are structurally distant and do not outweigh the class-consistent high-bioavailability evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the evidence set.",
    "The closest analogue, elbasvir, has bioavailability near the threshold (32%), so some uncertainty remains about the exact margin above 20%.",
    "Transfer scores are moderate rather than very high, and no human IV-comparison data for the exact query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

